import java.util.*;
import java.io.*;

public class cf111c_variant5 {
    public static int n, m, maxMask;
    public static int[][][] dp;
    public static int[] countOnes;

    public static int bitCount(int x) {
        int count = 0;
        while (x != 0) {
            count += (x & 1);
            x >>= 1;
        }
        return count;
    }

    public static boolean isPatternValid(int a, int b, int c) {
        int combined = (maxMask - 1) & (b | (b << 1) | (b >> 1) | a | c);
        return combined == maxMask - 1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        m = scanner.nextInt();
        if (n < m) {
            int temp = n; n = m; m = temp;
        }
        maxMask = 1 << m;
        dp = new int[n + 1][maxMask][maxMask];
        countOnes = new int[maxMask];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < maxMask; j++) {
                Arrays.fill(dp[i][j], 100);
            }
        }

        for (int i = 0; i < maxMask; i++) {
            countOnes[i] = bitCount(i);
            dp[0][0][i] = 0;
        }

        for (int rowIdx = 1; rowIdx <= n; rowIdx++) {
            for (int prevMask = 0; prevMask < maxMask; prevMask++) {
                for (int currMask = 0; currMask < maxMask; currMask++) {
                    for (int nextMask = 0; nextMask < maxMask; nextMask++) {
                        if (dp[rowIdx - 1][prevMask][nextMask] != 100 && isPatternValid(prevMask, nextMask, currMask)) {
                            dp[rowIdx][currMask][nextMask] = Math.min(dp[rowIdx][currMask][nextMask], dp[rowIdx - 1][prevMask][nextMask] + countOnes[nextMask]);
                        }
                    }
                }
            }
        }

        int minVal = Integer.MAX_VALUE;
        for (int i = 0; i < maxMask; i++) {
            minVal = Math.min(dp[n][i][0], minVal);
        }
        System.out.println(n * m - minVal);
    }
}
